NAME = 'TpiKJPB: King Jems Pisin Baibel'
BOOK = 'Ephesians'

CHAPTERS = {
    1: {
        1: '¶ Pol, wanpela aposel bilong Jisas Kraist long laik bilong God, i go long ol seint husat i stap long Efesas, na long ol man yu inap bilip long ol insait long Kraist Jisas.',
        2: 'Marimari i ken stap long yupela, na bel isi, i kam long God, Papa bilong yumi, na i kam long Bikpela Jisas Kraist.',
        3: '¶ Blesing i stap long God na Papa bilong Bikpela bilong yumi Jisas Kraist, husat i bin blesim yumi wantaim olgeta blesing long sait bilong spirit long ol ples antap long heven insait long Kraist,',
        4: 'Bilong bihainim olsem em i bin makim yumi insait long em bipo long stat bilong ol as ston bilong dispela graun, inap long yumi ken stap holi na i no gat asua long ai bilong em long laikim tru,',
        5: 'Taim em i bin makim yumi bipo yet long kisim nem pikinini long wok bilong Jisas Kraist i go long em yet, bilong bihainim gutpela amamas bilong laik bilong em,',
        6: 'I go long biknem bilong glori bilong marimari bilong em, we insait long en em i bin mekim yumi orait long ai bilong em insait long man i stap klostu tru long bel.',
        7: 'Insait long husat yumi gat pasin bilong baim bek long wok bilong blut bilong em, pasin bilong lusim ol sin, bilong bihainim ol samting i dia tru bilong marimari bilong em,',
        8: 'We long en em i bin pulap tru i go long yumi long olgeta save tru na pasin bilong yusim save,',
        9: 'Taim em i mekim yumi save long samting hait bilong laik bilong em, bilong bihainim gutpela amamas bilong em, dispela em i bin wokim tingting long en insait long em yet.',
        10: 'Inap long insait long wok bilong tilim bilong ol taim i pulap em i ken bungim wantaim, insait long wanpela, olgeta samting insait long Kraist, dispela i stap long heven, na dispela i stap long dispela graun wantaim, yes, insait long em.',
        11: 'Insait long husat tu yumi bin kisim samting papa i givim pikinini, taim em i makim yumi bipo yet bilong bihainim dispela tingting bilong mekim samting bilong em husat i wokim olgeta samting i bihainim tok helpim bilong laik bilong em yet.',
        12: 'Inap long yumi ken stap long go long biknem bilong glori bilong em, husat pastaim i putim bilip long Kraist.',
        13: 'Long husat yupela tu i putim bilip, bihain long yupela i harim tok bilong tok tru, gutnius bilong kisim bek bilong yupela. Long husat tu bihain long yupela i bin bilip, God i pasim yupela wantaim dispela Spirit holi bilong promis,',
        14: 'Husat i promis bilong samting Papa i givim pikinini bilong yumi inap long pasin bilong baim bek bilong dispela samting em i baim bilong holim, i go long biknem bilong glori bilong em.',
        15: '¶ Olsem na mi tu, bihain long mi harim stori long bilip tru bilong yupela insait long Bikpela Jisas, na laikim tru i go long olgeta seint,',
        16: 'I no lusim pasin long givim tok tenkyu long God long yupela, taim mi kolim ol nem bilong yupela long ol prea bilong mi.',
        17: 'Inap long God bilong Bikpela bilong yumi Jisas Kraist, Papa bilong glori, i ken givim i go long yupela dispela spirit bilong save tru na kamapim tok hait insait long save bilong em,',
        18: 'Taim ol ai bilong gutpela save bilong yupela i kisim lait, inap long yupela i ken save wanem samting em i hop bilong singaut bilong em, na wanem ol samting i dia tru bilong glori bilong samting papa i givim pikinini bilong em long ol seint,',
        19: 'Na wanem samting em i planti moa yet bilong bikpela bilong pawa bilong em i kam long yumi husat i bilip, bilong bihainim wok bilong strongpela pawa bilong em,',
        20: 'Dispela em i wokim insait long Kraist, taim em i kirapim em long dai, na putim em long han sut bilong em yet long ol ples long heven,',
        21: 'Antap longwe moa long olgeta hetman bilong gavman, na pawa, na strong, na biknem bilong bosim, na olgeta wan wan nem long ol i kolim, i no long dispela graun nau tasol, tasol tu long dispela samting long kamap bihain.',
        22: 'Na em i bin putim olgeta samting aninit long tupela fut bilong em, na givim em long stap het long bosim olgeta samting long sios,',
        23: 'Dispela em i bodi bilong em, dispela pulap bilong em husat i pulimapim olgeta long olgeta.',
    },
    2: {
        1: '¶ Na yupela em i bin givim laip, husat i bin stap daiman long ol pasin bilong sakim lo na ol sin.',
        2: 'We insait long en long taim bipo yupela i wokabaut bilong bihainim pasin bilong dispela graun, bilong bihainim hetman bilong pawa bilong skai, dispela spirit nau i wok insait long ol pikinini bilong sakim tok.',
        3: 'Namel long husat tu yumi olgeta i gat pasin bilong yumi long ol taim bipo insait long ol aigris bilong bodi bilong yumi, taim yumi inapim ol laik bilong bodi na bilong tingting. Na long bodi sait yumi bin stap ol pikinini bilong belhat tru, yes, olsem ol arapela.',
        4: '¶ Tasol God, husat i pulap long pasin sori, long bikpela laikim tru bilong em we wantaim dispela em i laikim yumi tru,',
        5: 'Yes, taim yumi stap daiman insait long ol sin, em i bin givim laip long yumi wantaim wantaim Kraist, (long marimari em i kisim bek yupela.)',
        6: 'Na em i bin kirapim yumi wantaim, na mekim yumi sindaun wantaim long ol ples long heven insait long Kraist Jisas.',
        7: 'Inap long, long ol taim i laik kamap em i ken soim ol samting i dia tru i planti moa yet bilong marimari bilong em long gutpela pasin bilong em i kam long yumi long wok bilong Kraist Jisas.',
        8: 'Long wanem, long marimari God i kisim bek yupela long wok bilong bilip tru. Na dispela i no kam long yupela yet, em i presen bilong God,',
        9: 'I no long ol wok, nogut wanpela man i ken litimapim nating em yet.',
        10: 'Long wanem, yumi stap ol wok bilong em, samting em i kamapim long nating insait long Kraist Jisas i go long ol gutpela wok, dispela God i bin makim bipo long yumi ken wokabaut insait long ol.',
        11: '¶ Olsem na holim tingting, long taim yupela i stap long taim bipo ol man i no Ju long bodi, husat ol husat ol i kolim Lain Bilong Katim Skin long bodi ol i wokim long ol han i kolim Lain Bilong i No Katim Skin,',
        12: 'Bikos long dispela taim yupela i no gat Kraist, taim yupela i stap ol ausait man long kantri bilong Isrel, na ol ausait man long ol kontrak bilong promis, taim yupela i no gat hop, na yupela i no gat God long dispela graun,',
        13: 'Tasol nau insait long Kraist Jisas yupela husat sampela taim bipo i stap longwe tru, God i mekim yupela stap klostu, long wok bilong blut bilong Kraist.',
        14: '¶ Long wanem, em i bel isi bilong yumi, husat i bin mekim tupela wanpela, na husat i bin brukim i go daun dispela namel stret banis bilong brukim i stap namel long yumi,',
        15: 'Taim em i bin pinisim olgeta, long bodi bilong em, dispela pasin birua, yes, lo bilong ol tok strong i stap insait long ol lo em i makim, bilong mekim insait long em yet, long tupela, wanpela nupela man, na mekim bel isi kamap olsem.',
        16: 'Na inap long em i ken mekim wanbel pasin i kamap gen long tupela i go long God insait long wanpela bodi long wok bilong diwai kros, taim em i kilim i dai dispela pasin birua long en.',
        17: 'Na em i bin kam na autim tok long bel isi long yupela husat i stap longwe tru, na long ol husat i stap klostu.',
        18: 'Long wanem, long wok bilong em yumitupela wantaim i gat rot i go long Papa long wanpela Spirit.',
        19: 'Olsem na nau yupela i no stap moa ol ausait man na ol man bilong narapela kantri, tasol ol wan kantri wantaim ol seint, na bilong hauslain bilong God.',
        20: 'Na God i wokim yupela pinis antap long as ston bilong ol aposel na ol profet, Jisas Kraist em yet i stap nambawan ston bilong kona.',
        21: 'Long husat olgeta dispela haus i pas stret tru wantaim na em i kamap bikpela i go long wanpela tempel holi insait long Bikpela.',
        22: 'Insait long husat yupela tu God i wokim wantaim bilong wanpela ples bilong God bilong stap long en long wok bilong Spirit.',
    },
    3: {
        1: '¶ Long dispela as mi Pol, kalabusman bilong Jisas Kraist bilong helpim yupela ol man i no Ju,',
        2: 'Sapos yupela i bin harim stori long wok bilong tilim marimari bilong God, dispela em i givim long mi i go long yupela,',
        3: 'Olsem long wok bilong soim samting ples klia em i bin mekim mi long save long dispela samting hait, (olsem mi raitim long yupela bipo long ol wan wan tok,',
        4: 'We long en, taim yupela i ritim, yupela i ken kisim save long save bilong mi long samting hait bilong Kraist)',
        5: 'Dispela long ol arapela taim God i no mekim ol pikinini man bilong man long save long en, olsem em i kamap ples klia nau long ol aposel holi na ol profet bilong em long wok bilong Spirit,',
        6: 'Long ol man i no Ju i ken stap ol wan lain bilong kisim samting papa i givim pikinini, na bilong dispela bodi stret, na ol man i kisim hap bilong promis bilong em insait long Kraist long wok bilong gutnius,',
        7: 'We long en God i mekim mi wanpela wokman, bilong bihainim presen bilong marimari bilong God em i givim mi long pawa i wok wantaim pawa bilong em.',
        8: 'Long mi, husat i stap liklik moa long las man bilong olgeta seint, em i givim dispela marimari, inap long mi ken autim tok namel long ol man i no Ju ol dispela samting i dia tru bilong Kraist ol man i no inap painimaut olgeta,',
        9: 'Na long mekim olgeta man luksave long pasin poroman bilong dispela samting hait em i wanem samting, dispela em i bin haitim insait long God i stat long stat bilong dispela graun, husat i kamapim olgeta samting long nating long wok bilong Jisas Kraist,',
        10: 'Long dispela as, long nau long ol hetman bilong gavman na ol man i gat pawa long ol ples long heven, long wok bilong sios, i ken save long dispela planti kain kain save tru bilong God,',
        11: 'Bilong bihainim dispela tingting bilong mekim samting oltaim oltaim em i tingting bilong mekim insait long Kraist Jisas, Bikpela bilong yumi.',
        12: 'Long husat yumi gat pasin bilong i no pret na yumi ken go long em wantaim strongpela bilip long wok bilong bilip tru bilong em.',
        13: 'Olsem na mi gat laik long yupela i no ken hap i dai long ol bikpela hevi bilong mi bilong helpim yupela, dispela em i glori bilong yupela.',
        14: '¶ Long dispela as mi lindaunim tupela skru bilong mi i go long Papa bilong Bikpela bilong yumi Jisas Kraist,',
        15: 'Long husat dispela famili olgeta bilong heven na dispela graun i kisim nem,',
        16: 'Inap long em i ken oraitim yupela, bilong bihainim ol samting i dia tru bilong glori bilong em, long yupela i ken kisim strong wantaim strong long wok bilong Spirit bilong em insait long dispela insait man,',
        17: 'Inap long Kraist i ken stap insait long ol bel bilong yupela long wok bilong bilip tru, inap long yupela, taim yupela i gat ol rop daunbilo na i strong tru insait long laikim tru,',
        18: 'I ken stap inap long save wantaim olgeta seint long brait, na longpela, na dip, na antap em i wanem,',
        19: 'Na long yupela i ken save laikim tru bilong Kraist, dispela i winim save bilong man, inap long yupela i ken pulap wantaim olgeta samting God i pulap long en.',
        20: 'Nau i go long em husat i inap long mekim samting i planti moa yet tru antap long olgeta samting yumi askim o tingim, bilong bihainim dispela pawa i wok insait long yumi,',
        21: 'Long em glori i ken stap insait long sios long wok bilong Kraist Jisas namel long olgeta taim bihain, taim dispela graun i no gat pinis. Amen.',
    },
    4: {
        1: '¶ Olsem na mi, kalabusman bilong Bikpela, i askim yupela plis strong long yupela i ken wokabaut i inap long dispela wok we wantaim dispela em i singautim yupela,',
        2: '¶ Wantaim olgeta pasin daun na pasin bilong stap isi, wantaim pasin bilong karim pen longpela taim, taim yupela i stap isi wanpela i go long narapela insait long laikim tru,',
        3: 'Taim yupela i traim long holimpas wanbel pasin bilong Spirit insait long kalabus bilong bel isi.',
        4: 'I gat wanpela bodi, na wanpela Spirit, yes, olsem God i singautim yupela long wanpela hop bilong singaut bilong yupela,',
        5: 'Wanpela Bikpela, wanpela bilip tru, wanpela baptais,',
        6: 'Wanpela God na Papa bilong olgeta, husat i stap antap long olgeta, na namel long olgeta, na insait long yupela olgeta.',
        7: 'Tasol long olgeta wan wan bilong yumi God i givim marimari bilong bihainim skel bilong presen bilong Kraist.',
        8: 'Olsem na em i tok, Taim em i go antap long antap, em i stiaim ol kalabus i go kalabus, na givim ol presen i go long ol man.',
        9: '(Nau long em i bin go antap, em i wanem samting tasol long em tu i bin go daun pastaim insait long ol ples daun insait long dispela graun?',
        10: 'Em husat i bin go daun em i man stret tu husat i bin go antap longwe antap moa long olgeta heven, inap long em i ken pulimapim olgeta samting.)',
        11: 'Na em i givim sampela, ol aposel, na sampela, ol profet, na sampela, ol ivanselis, na sampela, ol pasta na ol tisa,',
        12: 'Bilong inapim tru ol seint, bilong wok bilong dispela wok bilong God, bilong strongim bilip bilong bodi bilong Kraist,',
        13: 'Inap long taim yumi olgeta i kam long wanbel pasin bilong bilip tru, na bilong save bilong Pikinini Man bilong God, i go long wanpela man i inap tru, i go long skel bilong longpela bilong pulap bilong Kraist.',
        14: 'Inap long i stat long nau i go yumi i no ken stap moa ol pikinini, na kirap nabaut i kam i go, na olgeta wan wan win bilong skul i karim yumi nabaut, long ol trik bilong ol man, na trik pasin bilong save stret, we long dispela ol i wet hait long giaman.',
        15: 'Tasol taim yumi toktok long tok tru insait long laikim tru, yumi ken kamap bikpela insait long em long olgeta samting, husat i het, yes, Kraist.',
        16: 'Long husat olgeta hap bilong bodi i pas wantaim na i pas strong long dispela samting long olgeta wan wan skru bilong bun i inapim, bilong bihainim gutpela wok i gat pawa bilong skel bilong olgeta wan wan hap, taim dispela i mekim bodi i kamap planti moa bilong strongim bilip bilong dispela yet long pasin bilong laikim tru.',
        17: '¶ Olsem na dispela mi tok, na tokaut klia insait long Bikpela, long i stat nau i go yupela i no ken wokabaut moa olsem ol arapela man i no Ju i wokabaut, long tingting nating bilong tingting bilong ol,',
        18: 'Taim gutpela save bilong ol i go tudak, taim ol i stap ausait long laip bilong God long wok bilong dispela longlong pasin i stap insait long ol, bilong wanem, bel bilong ol i aipas.',
        19: 'Husat, taim ol i abrusim mak bilong pilim, i bin givim ol yet i go olgeta long pasin bilong mangal nogut, long wokim olgeta pasin i no klin wantaim pasin gridi.',
        20: 'Tasol yupela i no bin lainim Kraist olsem,',
        21: 'Sapos em i olsem long yupela i bin harim em, na yupela i bin kisim skul long em, olsem tok tru i stap insait long Jisas,',
        22: 'Long yupela i mas rausim, long sait bilong pasin bilong bipo, dispela olpela man, husat i bagarap bilong bihainim ol aigris i pulap long giaman,',
        23: 'Na stap nupela gen long spirit bilong tingting bilong yupela,',
        24: 'Na long yupela i mas putim dispela nupela man, husat i bihainim God na em i kamapim em long nating long stretpela pasin na pasin holi tru tru.',
        25: 'Olsem na taim yupela i rausim pasin giaman, toktok olgeta wan wan man long tok tru wantaim man i stap klostu long em. Long wanem, yumi stap ol hap bilong bodi wanpela bilong narapela.',
        26: 'Yupela i ken stap belhat, na no ken mekim sin. No ken larim san i go daun antap long belhat tru bilong yupela.',
        27: 'Na tu yupela i no ken givim spes long Seten.',
        28: 'Larim em husat i stil i no ken stil moa, tasol mobeta, larim em hatwok, taim em i wokim wantaim tupela han bilong em dispela samting i gutpela, inap long em i ken gat long givim long em husat i gat nid.',
        29: 'No ken larim toktok i bagarap i kam ausait long maus bilong yupela, tasol dispela samting i gutpela long yusim bilong strongim bilip, inap long em i ken wokim marimari i go long ol man i harim.',
        30: 'Na no ken bagarapim bel bilong Spirit holi bilong God, we long dispela God i pasim yupela inap long de bilong pasin bilong baim bek.',
        31: 'Rausim i go longwe long yupela olgeta pasin bilong bel i pait tru, na belhat tru, na belhat, na nois nabaut, na toktok nogut, wantaim olgeta bel nogut long narapela.',
        32: 'Na yupela i mas mekim gutpela pasin wanpela i go long narapela, wantaim bel i no strong, taim yupela i lusim rong wanpela i go long narapela, yes, olsem God, bilong tingim Kraist, i bin lusim ol rong bilong yupela.',
    },
    5: {
        1: '¶ Olsem na yupela i mas stap ol man bilong bihainim God, olsem ol pikinini i dia.',
        2: 'Na wokabaut insait long pasin bilong laikim tru, olsem Kraist tu i bin laikim tru yumi, na em i bin givim em yet long helpim yumi, wanpela ofa na sakrifais i go long God bilong wanpela smel i gat switpela test.',
        3: '¶ Tasol pasin pamuk, na olgeta pasin i no klin, o pasin mangal, no ken larim ol i kolim dispela wanpela taim namel long yupela, olsem em i gutpela long ol seint,',
        4: 'Na tu ol pasin doti tru, o ol kranki toktok, o pasin bilong wokim pani, dispela i no fit long ol seint. Tasol mobeta, givim tok tenkyu.',
        5: 'Long wanem, yupela i save long dispela, long i no gat pamuk man, o man i no klin, o man bilong mangal, husat i man bilong lotuim piksa bilong god giaman, husat i gat wanpela samting papa i givim pikinini insait long kingdom bilong Kraist na God.',
        6: 'No ken larim wanpela man giamanim yupela wantaim ol toktok nating. Long wanem, bilong tingim ol dispela samting belhat tru bilong God i kam antap long ol pikinini bilong sakim tok.',
        7: 'Olsem na yupela i no ken stap ol man bilong kisim hap wantaim ol.',
        8: 'Long wanem, sampela taim bipo yupela i stap long tudak, tasol nau yupela i stap lait insait long Bikpela. Wokabaut olsem ol pikinini bilong lait,',
        9: '(Long wanem, kaikai bilong Spirit i stap insait long olgeta gutpela pasin na stretpela pasin na tok tru,)',
        10: 'Taim yupela i pruvim wanem samting i orait long ai bilong Bikpela.',
        11: 'Na no ken gat poroman pasin wantaim ol wok bilong tudak i no karim gutpela kaikai, tasol mobeta yumi krosim ol.',
        12: 'Long wanem, em i samting bilong sem, yes, long toktok long sait bilong ol dispela samting, dispela ol i mekim hait.',
        13: 'Tasol olgeta dispela samting yumi krosim i kamap ples klia long lait. Long wanem, wanem samting i mekim samting kamap ples klia em i lait.',
        14: 'Olsem na em i tok, Kirap, yu husat i slip, na kirap long dai, na Kraist bai givim yu lait.',
        15: 'Lukluk gut nau long yupela i wokabaut wantaim ai i op, i no olsem ol krankiman, tasol olsem saveman,',
        16: 'Taim yupela i baim bek taim, bilong wanem, ol de i nogut.',
        17: 'Olsem na yupela i no ken stap man i no gat save tru, tasol yupela i mas gat save long laik bilong Bikpela em i wanem.',
        18: 'Na no ken spak wantaim wain, we long en em i tumas, tasol stap pulap wantaim Spirit,',
        19: 'Taim yupela i toktok long yupela yet long ol sam na ol song bilong lotu na ol song long sait bilong spirit, taim yupela i singim song na wokim musik insait long bel bilong yupela i go long Bikpela.',
        20: 'Taim yupela i givim tok tenkyu olgeta taim long olgeta samting i go long God na Papa long nem bilong Bikpela bilong yumi Jisas Kraist,',
        21: '¶ Taim yupela i putim yupela yet wanpela i aninit long narapela insait long pret long God.',
        22: 'Ol maritmeri, putim yupela yet aninit long ol man bilong yupela yet, olsem yupela i mekim i go long Bikpela.',
        23: 'Long wanem, maritman em i het bilong maritmeri, yes, olsem Kraist em i het bilong sios. Na em i man bilong kisim bek bodi.',
        24: 'Olsem na olsem sios i aninit long Kraist, olsem tasol larim ol maritmeri stap aninit long ol man bilong ol yet long olgeta wan wan samting.',
        25: 'Ol maritman, laikim tru ol meri bilong yupela, yes, olsem Kraist tu i laikim tru sios, na givim em yet bilong en,',
        26: 'Inap long em i ken mekim sios kamap holi na klinim dispela wantaim waswas bilong wara long wok bilong tok bilong God,',
        27: 'Inap long em i ken bringim dispela long em yet wanpela sios i gat glori, taim em i no gat mak, o hap i no stretpela tru, o wanpela kain samting, tasol long dispela i ken stap holi na i no gat mak nogut.',
        28: 'Olsem tasol ol man i mas laikim tru ol meri bilong ol olsem ol bodi bilong ol yet. em husat i laikim tru meri bilong em i laikim tru em yet.',
        29: 'Long wanem, i no gat yet wanpela man i bin hetim bodi bilong em yet. Tasol em i givim kaikai na laikim tru dispela, yes, olsem Bikpela i laikim tru sios.',
        30: 'Long wanem, yumi stap ol hap bilong bodi bilong em, bilong mit bilong em, na bilong ol bun bilong em.',
        31: 'Long dispela as man bai lusim papa na mama bilong em, na em bai pas wantaim meri bilong em, na tupela bai stap wanpela bodi.',
        32: 'Dispela em i wanpela bikpela samting hait. Tasol mi toktok long sait bilong Kraist na sios.',
        33: 'Tasol larim olgeta wan wan bilong yupela stret i ken laikim tru meri bilong em olsem, yes, olsem em yet. Na maritmeri i mas lukluk gut long em i givim biknem tru long man bilong em.',
    },
    6: {
        1: '¶ Ol pikinini, bihainim tok bilong papamama bilong yupela insait long Bikpela. Long wanem, dispela em i stretpela.',
        2: 'Givim ona long papa na mama bilong yu, (dispela em i namba wan tok strong wantaim promis,)',
        3: 'Inap long em i ken go gutpela long yu, na yu ken stap laip longpela taim long dispela graun.',
        4: 'Na, yupela ol papa, no ken skrapim bel bilong ol pikinini bilong yupela long belhat tru, tasol lukautim ol insait long lukaut na strongpela skul bilong Bikpela.',
        5: 'Ol wokboi, bihainim tok long ol husat i stap ol bosman bilong yupela bilong bihainim bodi sait, wantaim pret na guria, wantaim bel bilong yupela i gat wanpela tingting, olsem yupela i mekim i go long Kraist,',
        6: 'I no wantaim pasin bilong man i ken lukim, olsem ol man bilong amamasim bel bilong ol man, tasol olsem ol wokboi bilong Kraist, taim yupela i mekim laik bilong God i kam long bel.',
        7: 'Wantaim gutpela bel mekim wok, olsem yupela i mekim long Bikpela, na i no long ol man,',
        8: 'Taim yupela i save long wanem gutpela samting wanpela man i mekim, dispela wankain samting bai em i kisim long Bikpela, sapos em i slevman o friman.',
        9: 'Na, yupela ol bosman, mekim ol wankain samting long ol, taim yupela i stap isi long pasin bilong toktok long bagarapim ol, taim yupela i save long Bosman bilong yupela tu i stap long heven. Na tu i no gat pasin bilong tingim namba bilong ol man wantaim em.',
        10: '¶ Na las, ol brata bilong mi, stap strong insait long Bikpela, na insait long pawa bilong strong bilong em.',
        11: 'Putim olgeta klos pait bilong God, inap long yupela i ken stap inap long sanap na birua long ol trik bilong Seten.',
        12: 'Long wanem, yumi no pait birua long bodi na blut, tasol yumi birua long ol hetman bilong gavman, birua long ol pawa, birua long ol hetman bilong tudak bilong dispela graun, birua long ol pasin nogut long sait bilong spirit long ol ples antap.',
        13: 'Olsem na kisim i go long yupela olgeta klos pait bilong God, inap long yupela i ken stap inap long sanap strong na birua long dispela de nogut, na taim yupela i bin mekim olgeta samting, long sanap.',
        14: 'Olsem na sanap, taim ol namel bilong bel bilong yupela i pas nabaut wantaim tok tru, na taim yupela i gat klos pait bilong bros bilong stretpela pasin,',
        15: 'Na ol fut bilong yupela i redi wantaim su bilong gutnius bilong bel isi.',
        16: 'Na antap long olgeta, kisim plang bilong bilip tru, we wantaim dispela yupela bai stap inap long kilim i dai olgeta liklik spia paia bilong dispela man nogut.',
        17: 'Na kisim hat ain bilong kisim bek, na bainat bilong Spirit, dispela em i tok bilong God,',
        18: 'Taim yupela i beten olgeta taim wantaim olgeta prea na autim askim insait long Spirit, na was long en wantaim olgeta pasin bilong stap strong yet na autim askim bilong helpim olgeta seint,',
        19: '¶ Na long mi, inap long pasin bilong toktok God i ken givim long mi, inap long mi ken opim maus bilong mi wantaim pasin bilong i no pret, long mekim ol man long save long samting hait bilong gutnius,',
        20: 'Bilong dispela mi stap wanpela mausman bilong gavman insait long ol kalabus, inap long insait long en mi ken toktok wantaim pasin bilong i no pret, olsem mi mas toktok.',
        21: 'Tasol inap long yupela tu i ken save long ol samting bilong mi, na long mi stap olsem wanem, Tikikas, wanpela brata i stap klostu tru long bel na wanpela wokman insait long Bikpela yu inap bilip long em, bai mekim yupela long save long olgeta samting,',
        22: 'Husat mi bin salim long yupela bilong dispela as stret, inap long yupela i ken save long ol samting bilong mipela, na long em i ken givim bel isi long ol bel bilong yupela.',
        23: 'Bel isi i ken stap long ol brata, na laikim tru wantaim bilip tru, i kam long God Papa na Bikpela Jisas Kraist.',
        24: 'Marimari i ken stap wantaim ol olgeta husat i laikim tru Bikpela bilong yumi Jisas Kraist wantaim trupela bel. Amen.',
    },
}
